{
  "name": "@super-pocock-ai/memory-core",
  "version": "2.3.30",
  "description": "持久化记忆系统，基于 SQLite FTS5 和 BM25 搜索（OpenCode/Bun 运行时）",
  "main": "dist/index.js",
  "module": "dist/index.mjs",
  "types": "dist/index.d.ts",
  "exports": {
    ".": {
      "import": "./dist/index.mjs",
      "require": "./dist/index.js",
      "types": "./dist/index.d.ts"
    },
    "./tui": {
      "import": "./dist/tui.mjs"
    }
  },
  "files": [
    "dist"
  ],
  "scripts": {
    "build": "tsup",
    "test": "vitest run",
    "test:watch": "vitest",
    "typecheck": "tsc --noEmit"
  },
  "dependencies": {
    "@opencode-ai/plugin": "latest",
    "@opentui/solid": "^0.4.3",
    "zod": "^3.23.0"
  },
  "devDependencies": {
    "@types/node": "^20.0.0",
    "typescript": "^5.5.0",
    "tsup": "^8.0.0",
    "vitest": "^2.0.0"
  },
  "keywords": [
    "opencode",
    "memory",
    "sqlite",
    "fts5",
    "bm25",
    "checkpoint"
  ],
  "license": "MIT"
}
